fn is_palindrome(text: Vec<char>) -> bool {
    let len = text.len();
    for i in 0..len / 2 {
        let left_char = text[i];
        let right_char = text[len - 1 - i];

        if left_char.to_ascii_lowercase() != right_char.to_ascii_lowercase() {
            return false;
        }
    }
    true
}